#include <stdio.h>
#define MAX 100

int stack[MAX], top = -1;

void push(int val) {
    if (top == MAX - 1) { printf("Stack Overflow\n"); return; }
    stack[++top] = val;
}

int pop() {
    if (top == -1) { printf("Stack Underflow\n"); return -1; }
    return stack[top--];
}

int peek() {
    return (top == -1) ? -1 : stack[top];
}

int main() {
    push(10); push(20); push(30);
    printf("Top: %d\n", peek());
    printf("Popped: %d\n", pop());
    printf("New Top: %d\n", peek());
    return 0;
}

