#include <stdio.h>
#define MAX 100

int heap[MAX], heapSize = 0;

void insert(int val) {
    heap[heapSize] = val;
    int i = heapSize++;
    while (i > 0 && heap[(i-1)/2] < heap[i]) {
        int temp = heap[i]; heap[i] = heap[(i-1)/2]; heap[(i-1)/2] = temp;
        i = (i - 1) / 2;
    }
}

int extractMax() {
    int max = heap[0];
    heap[0] = heap[--heapSize];
    int i = 0;
    while (1) {
        int l = 2*i+1, r = 2*i+2, largest = i;
        if (l < heapSize && heap[l] > heap[largest]) largest = l;
        if (r < heapSize && heap[r] > heap[largest]) largest = r;
        if (largest == i) break;
        int temp = heap[i]; heap[i] = heap[largest]; heap[largest] = temp;
        i = largest;
    }
    return max;
}

int main() {
    insert(3); insert(10); insert(7); insert(1);
    printf("Max: %d\n", extractMax());
    return 0;
}

