#define V 5

int minKey(int key[], int inMST[]) {
    int min = INT_MAX, minIdx = -1;
    for (int v = 0; v < V; v++)
        if (!inMST[v] && key[v] < min)
            min = key[v], minIdx = v;
    return minIdx;
}

void primMST(int graph[V][V]) {
    int parent[V], key[V], inMST[V];
    for (int i = 0; i < V; i++) key[i] = INT_MAX, inMST[i] = 0;
    key[0] = 0; parent[0] = -1;
    for (int count = 0; count < V - 1; count++) {
        int u = minKey(key, inMST);
        inMST[u] = 1;
        for (int v = 0; v < V; v++)
            if (graph[u][v] && !inMST[v] && graph[u][v] < key[v])
                parent[v] = u, key[v] = graph[u][v];
    }
    for (int i = 1; i < V; i++)
        printf("Edge %d-%d: %d\n", parent[i], i, graph[i][parent[i]]);
}

