void kadane(int arr[], int n) {
    int maxSoFar = INT_MIN, maxEndingHere = 0;
    int start = 0, end = 0, tempStart = 0;
    for (int i = 0; i < n; i++) {
        maxEndingHere += arr[i];
        if (maxSoFar < maxEndingHere) {
            maxSoFar = maxEndingHere;
            start = tempStart;
            end = i;
        }
        if (maxEndingHere < 0) {
            maxEndingHere = 0;
            tempStart = i + 1;
        }
    }
    printf("Max Sum: %d from index %d to %d\n", maxSoFar, start, end);
}

