#include <stdio.h>
#include <string.h>

void computeLPS(char* pattern, int m, int* lps) {
    int len = 0, i = 1;
    lps[0] = 0;
    while (i < m) {
        if (pattern[i] == pattern[len]) lps[i++] = ++len;
        else if (len) len = lps[len - 1];
        else lps[i++] = 0;
    }
}

void kmpSearch(char* text, char* pattern) {
    int n = strlen(text), m = strlen(pattern);
    int lps[m];
    computeLPS(pattern, m, lps);
    int i = 0, j = 0;
    while (i < n) {
        if (text[i] == pattern[j]) { i++; j++; }
        if (j == m) {
            printf("Found at index %d\n", i - j);
            j = lps[j - 1];
        } else if (i < n && text[i] != pattern[j]) {
            if (j) j = lps[j - 1];
            else i++;
        }
    }
}

int main() {
    char text[] = "ABABDABACDABABCABAB";
    char pattern[] = "ABABCABAB";
    kmpSearch(text, pattern);
    return 0;
}

#include <stdio.h>
#include <string.h>
#define d 256
#define q 101

void rabinKarp(char* text, char* pattern) {
    int n = strlen(text), m = strlen(pattern);
    int h = 1, patHash = 0, txtHash = 0;
    for (int i = 0; i < m - 1; i++) h = (h * d) % q;
    for (int i = 0; i < m; i++) {
        patHash = (d * patHash + pattern[i]) % q;
        txtHash = (d * txtHash + text[i]) % q;
    }
    for (int i = 0; i <= n - m; i++) {
        if (patHash == txtHash) {
            int j;
            for (j = 0; j < m; j++)
                if (text[i+j] != pattern[j]) break;
            if (j == m) printf("Found at index %d\n", i);
        }
        if (i < n - m) {
            txtHash = (d * (txtHash - text[i] * h) + text[i + m]) % q;
            if (txtHash < 0) txtHash += q;
        }
    }
}

int main() {
    char text[] = "GEEKS FOR GEEKS";
    char pattern[] = "GEEK";
    rabinKarp(text, pattern);
    return 0;
}

#include <stdio.h>
#include <string.h>

void expandAroundCenter(char* s, int left, int right, int* start, int* maxLen) {
    int n = strlen(s);
    while (left >= 0 && right < n && s[left] == s[right]) {
        left--; right++;
    }
    if (right - left - 1 > *maxLen) {
        *maxLen = right - left - 1;
        *start = left + 1;
    }
}

void longestPalindrome(char* s) {
    int n = strlen(s), start = 0, maxLen = 1;
    for (int i = 0; i < n; i++) {
        expandAroundCenter(s, i, i, &start, &maxLen);
        expandAroundCenter(s, i, i + 1, &start, &maxLen);
    }
    printf("Longest Palindrome: ");
    for (int i = start; i < start + maxLen; i++)
        printf("%c", s[i]);
    printf(" (length %d)\n", maxLen);
}

int main() {
    char s[] = "babad";
    longestPalindrome(s);
    return 0;
}

