void sieve(int n) {
    int isPrime[n + 1];
    memset(isPrime, 1, sizeof(isPrime));
    isPrime[0] = isPrime[1] = 0;
    for (int p = 2; p * p <= n; p++) {
        if (isPrime[p]) {
            for (int i = p * p; i <= n; i += p)
                isPrime[i] = 0;
        }
    }
    printf("Primes up to %d: ", n);
    for (int i = 2; i <= n; i++)
        if (isPrime[i]) printf("%d ", i);
    printf("\n");
}

