#include <stdio.h>

long long fastPow(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp % 2 == 1)
            result = (result * base) % mod;
        exp /= 2;
        base = (base * base) % mod;
    }
    return result;
}

int main() {
    printf("2^10 mod 1000 = %lld\n", fastPow(2, 10, 1000));
    printf("3^20 mod 1000000007 = %lld\n", fastPow(3, 20, 1000000007));
    return 0;
}

