// Recursive approach
long long factorialRecursive(int n) {
    if (n == 0 || n == 1) return 1;
    return n * factorialRecursive(n - 1);
}

// Iterative approach
long long factorialIterative(int n) {
    long long result = 1;
    for (int i = 2; i <= n; i++)
        result *= i;
    return result;
}

int main() {
    int n = 10;
    printf("%d! (recursive) = %lld\n", n, factorialRecursive(n));
    printf("%d! (iterative) = %lld\n", n, factorialIterative(n));
    return 0;
}

