int tsp(int graph[N][N], int visited[], int currPos, int n, int count, int cost) {
    if (count == n && graph[currPos][0]) {
        return cost + graph[currPos][0];
    }

    int ans = INT_MAX;

    for (int i = 0; i < n; i++) {
        if (visited[i] == 0 && graph[currPos][i]) {
            visited[i] = 1;

            ans = min(ans, tsp(graph, visited, i, n, count + 1,
                              cost + graph[currPos][i]));

            visited[i] = 0;
        }
    }

    return ans;
}

int main() {
    int graph[N][N] = {
        {0, 10, 15, 20},
        {10, 0, 35, 25},
        {15, 35, 0, 30},
        {20, 25, 30, 0}
    };

    int visited[N] = {0};
    visited[0] = 1;

    int result = tsp(graph, visited, 0, N, 1, 0);
    printf("Minimum travelling cost: %d\n", result);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#define MAX 3
#define MIN 2
struct BTreeNode {
    int val[MAX + 1], count;
    struct BTreeNode *child[MAX + 2];
};
typedef struct BTreeNode Node;
Node* createNode(int val, Node* child) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->val[1] = val;
    newNode->count = 1;
    newNode->child[0] = NULL;
    newNode->child[1] = child;
    return newNode;
}
void addValToNode(int val, int pos, Node* node, Node* child) {
    int j = node->count;
    while (j > pos) {
        node->val[j + 1] = node->val[j];
        node->child[j + 1] = node->child[j];
        j--;
    }
    node->val[j + 1] = val;
    node->child[j + 1] = child;
    node->count++;
}
void splitNode(int val, int* pval, int pos, Node* node, Node* child, Node** newNode) {
    int median, j;
    if (pos > MIN) median = MIN + 1;
    else median = MIN;
    *newNode = (Node*)malloc(sizeof(Node));
    j = median + 1;
    while (j <= MAX) {
        (*newNode)->val[j - median] = node->val[j];
        (*newNode)->child[j - median] = node->child[j];
        j++;
    }
    node->count = median;
    (*newNode)->count = MAX - median;
    if (pos <= MIN) addValToNode(val, pos, node, child);
    else addValToNode(val, pos - median, *newNode, child);
    *pval = node->val[node->count];
    (*newNode)->child[0] = node->child[node->count];
    node->count--;
}
int setVal(int val, Node* node, int* pval, Node** child) {
    int pos;
    if (!node) { *pval = val; *child = NULL; return 1; }
    if (val < node->val[1]) pos = 0;
    else {
        for (pos = node->count; (val < node->val[pos] && pos > 1); pos--);
        if (val == node->val[pos]) { printf("Duplicates not allowed\n"); return 0; }
    }
    if (setVal(val, node->child[pos], pval, child)) {
        if (node->count < MAX) { addValToNode(*pval, pos, node, *child); return 0; }
        else { splitNode(*pval, pval, pos, node, *child, child); return 1; }
    }
    return 0;
}
void insert(int val, Node** node) {
    int i; Node* child;
    if (setVal(val, *node, &i, &child)) {
        Node* newNode = createNode(i, child);
        newNode->child[0] = *node;
        *node = newNode;
    }
}
void inorder(Node* node) {
    if (node) {
        int i;
        for (i = 0; i < node->count; i++) {
            inorder(node->child[i]);
            printf("%d ", node->val[i + 1]);
        }
        inorder(node->child[i]);
    }
}
int main() {
    Node* root = NULL;
    insert(10, &root); insert(20, &root); insert(5, &root);
    insert(6, &root); insert(12, &root); insert(30, &root);
    insert(7, &root); insert(17, &root);
    printf("Inorder traversal: ");
    inorder(root);
    printf("\n");
    return 0;
}

